SELECT * FROM (
    SELECT t.*, ROWNUM rn FROM (
        SELECT 

        WHERE o.IS_DELETED = 0

            AND (o.ORDER_NO LIKE '%' || #{keyword} || '%' OR c.CUST_NAME LIKE '%' || #{keyword} || '%')

         AND o.STATUS = #{status} 
         AND o.CREATE_TIME >= #{startDate} 
         AND o.CREATE_TIME <  #{endDate} 

    ) t WHERE ROWNUM <= #{offset} + #{limit}
) WHERE rn > #{offset}

SELECT COUNT(1)
FROM HOTEL_ORDER o
LEFT JOIN CUSTOMER c ON o.CUSTOMER_ID = c.CUSTOMER_ID
WHERE o.IS_DELETED = 0

    AND (o.ORDER_NO LIKE '%' || #{keyword} || '%' OR c.CUST_NAME LIKE '%' || #{keyword} || '%')

 AND o.STATUS = #{status} 
 AND o.CREATE_TIME >= #{startDate} 
 AND o.CREATE_TIME <  #{endDate}

