UPDATE HOTEL_ORDER SET
    TOTAL_AMOUNT = #{totalAmount},
    UPDATE_TIME = F_NOW(),
    UPDATE_BY = #{updateBy}
WHERE ORDER_ID = #{orderId}

UPDATE HOTEL_ORDER SET
    STATUS = #{status},
    VERSION = VERSION + 1,
    UPDATE_TIME = F_NOW(),
    UPDATE_BY = #{updateBy}
WHERE ORDER_ID = #{orderId} AND VERSION = #{version}
